import{_ as a,o as r,c as d,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"ٹیکنالوجی سسٹم کا جامع جائزہ","description":"","frontmatter":{},"headers":[],"relativePath":"ur/60-技术体系总览.md","filePath":"ur/60-技术体系总览.md","lastUpdated":null}'),e={name:"ur/60-技术体系总览.md"};function l(i,t,n,h,s,u){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="ٹیکنالوجی-سسٹم-کا-جامع-جائزہ" tabindex="-1">ٹیکنالوجی سسٹم کا جامع جائزہ <a class="header-anchor" href="#ٹیکنالوجی-سسٹم-کا-جامع-جائزہ" aria-label="Permalink to &quot;ٹیکنالوجی سسٹم کا جامع جائزہ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>60</td></tr><tr><td>ماڈیول</td><td>ٹیکنالوجی اور توانائی کا نظام</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>ٹیکنالوجی سسٹم، قانون کی انجینئرنگ، حقیقت پر مبنی، قوانین کی بہتری، چار مراحل</td></tr></tbody></table><h2 id="_1-ٹیکنالوجی-سسٹم-کی-بنیادی-موقف" tabindex="-1">1. ٹیکنالوجی سسٹم کی بنیادی موقف <a class="header-anchor" href="#_1-ٹیکنالوجی-سسٹم-کی-بنیادی-موقف" aria-label="Permalink to &quot;1. ٹیکنالوجی سسٹم کی بنیادی موقف&quot;">​</a></h2><p>اینکر سمبیوٹک تہذیب کا ٹیکنالوجی سسٹم &quot;حقیقت پر مبنی، قوانین کی بہتری&quot; کے بنیادی اصول پر قائم ہے۔ اس اصول کے دو معنی ہیں: پہلا، حقیقی دنیا واحد حقیقی دنیا ہے، تمام ٹیکنالوجی ایجادات کو حقیقی طبیعی قوانین پر مبنی ہونا چاہیے، بنیادی تحفظ کے قوانین کی خلاف ورزی کرنے والے آلات کو خیالی طور پر ایجاد نہیں کیا جا سکتا؛ دوسرا، جب حقیقی سائنس اور ٹیکنالوجی کے ذریعے ابھی تک نہ چھوئے گئے شعبوں میں ضروریات پیدا ہوتی ہیں، تو موجودہ قوانین کی بنیاد پر منطقی طور پر بہتری کا تخمینہ لگانے کی اجازت ہے، اور سادگی کے قوانین میں پہلے سے تصدیق شدہ میکانزم کو انجینئرنگ کے لحاظ سے قابل عمل ٹیکنالوجی حل میں تبدیل کیا جا سکتا ہے۔</p><p>ہینگ یوآن ژو کا ٹیکنالوجی سسٹم روایتی معنوں میں &quot;سائنس اور ٹیکنالوجی&quot; اور &quot;سادگی&quot; کے دوہری تضاد نہیں ہے، بلکہ دونوں کے گہرے امتزاج کا &quot;قانون کی انجینئرنگ&quot; سسٹم ہے۔ سادگی کرنے والوں کی بنیادی قوانین کے بارے میں سمجھ ٹیکنالوجی کو نظریاتی سرحد فراہم کرتی ہے، جبکہ انجینئرنگ ٹیکنالوجی قوانین کی سمجھ کو بڑے پیمانے پر پیداوار اور عام کرنے کے قابل بنیادی ڈھانچے میں تبدیل کرتی ہے۔ اس امتزاج کی وجہ سے ٹیکنالوجی کی ترقی اب کچھ اہلکاروں کے اتفاقی دریافتوں پر منحصر نہیں ہے، بلکہ اینکر نیٹ ورک کے مسلسل تاثرات پر مبنی اجتماعی ارتقاء پر قائم ہے۔</p><h2 id="_2-ٹیکنالوجی-سسٹم-کی-پرت-دار-تعمیر" tabindex="-1">2. ٹیکنالوجی سسٹم کی پرت دار تعمیر <a class="header-anchor" href="#_2-ٹیکنالوجی-سسٹم-کی-پرت-دار-تعمیر" aria-label="Permalink to &quot;2. ٹیکنالوجی سسٹم کی پرت دار تعمیر&quot;">​</a></h2><p>ہینگ یوآن ژو ٹیکنالوجی سسٹم کو بنیادی قوانین کے ساتھ جوڑے کی گہرائی کے مطابق چار پرتوں میں تقسیم کیا گیا ہے:</p><table tabindex="0"><thead><tr><th>پرت</th><th>نام</th><th>خصوصیات</th><th>نمائندہ ٹیکنالوجیز</th></tr></thead><tbody><tr><td>پہلی پرت</td><td>حقیقی سائنس اور ٹیکنالوجی کی پرت</td><td>کلاسیکی طبیعیات اور جدید سائنس پر مبنی، سادگی کے قوانین شامل نہیں ہیں</td><td>بجلی، الیکٹرانکس، کمپیوٹر، خلائی پرواز</td></tr><tr><td>دوسری پرت</td><td>قانون کی طاقت افزائی کی پرت</td><td>موجودہ سائنس اور ٹیکنالوجی میں سادگی کے قوانین کے میکانزم کو شامل کرنا، کارکردگی میں چھلانگ لگانا</td><td>ضرب پھل کا تخمینہ انجن، توانائی کے معیاری کاری کی پیمائش</td></tr><tr><td>تیسری پرت</td><td>قانون کی انجینئرنگ کی پرت</td><td>براہ راست بنیادی قوانین کو انجینئرنگ کے شے کے طور پر لینا، نیا ٹیکنالوجی نمونہ بنانا</td><td>خلائی قانون کی شیڈولنگ ڈیوائس، کاپی آئینہ کا نظام، الگ تھلگ جگہ</td></tr><tr><td>چوتھی پرت</td><td>اینکر بنیادی ڈھانچے کی پرت</td><td>اینکر کو مرکز کے طور پر بین-جہات، بین-پرتی ٹیکنالوجی کی بنیاد</td><td>اینکر ہارڈویئر سرنی، بین-جہات مواصلاتی نیٹ ورک، سمبیوٹک تاثرات کا نظام</td></tr></tbody></table><p>چار پرتیں متبادل تعلق نہیں ہیں، بلکہ اوورلیپنگ تعلق ہیں۔ حقیقی سائنس اور ٹیکنالوجی کی پرت تمام اوپری پرتوں کی ٹیکنالوجیز کی مادی بنیاد ہے، قانون کی طاقت افزائی کی پرت منتقلی کا پل ہے، قانون کی انجینئرنگ کی پرت سمبیوٹک تہذیب کا ٹیکنالوجی مرکز ہے، اور اینکر بنیادی ڈھانچے کی پرت تہذیب کے جہت بڑھاؤ کی بنیادی ضمانت ہے۔ کسی بھی نئی ٹیکنالوجی کی تحقیق اور ترقی کو نیچے سے اوپر کی طرف پرت در پرت تصدیق کرنی چاہیے، حقیقی بنیاد کو چھوڑ کر براہ راست اعلیٰ سطحی ٹیکنالوجی بنانے کی اجازت نہیں ہے۔</p><h2 id="_3-ٹیکنالوجی-کی-تحقیق-اور-ترقی-کا-بنیادی-عمل" tabindex="-1">3. ٹیکنالوجی کی تحقیق اور ترقی کا بنیادی عمل <a class="header-anchor" href="#_3-ٹیکنالوجی-کی-تحقیق-اور-ترقی-کا-بنیادی-عمل" aria-label="Permalink to &quot;3. ٹیکنالوجی کی تحقیق اور ترقی کا بنیادی عمل&quot;">​</a></h2><p>ہینگ یوآن ژو ٹیکنالوجی کی تحقیق اور ترقی &quot;قانون کی سمجھ → میکانزم کی تصدیق → انجینئرنگ پروٹوٹائپ → معیاری بڑے پیمانے پر پیداوار → کھلا اشتراک&quot; کے پانچ قدمی عمل کی پیروی کرتی ہے:</p><ol><li><strong>قانون کی سمجھ</strong>: سادگی کرنے والے اور محققین مشترکہ طور پر ہدف قانون کے بارے میں گہرا تخمینہ لگاتے ہیں، ضرب پھل کے تخمینہ انجن کی مدد سے نظریاتی ماڈلنگ مکمل کرتے ہیں</li><li><strong>میکانزم کی تصدیق</strong>: الگ تھلگ جگہ میں چھوٹے پیمانے پر تجربات کیے جاتے ہیں، قانون کے میکانزم کی تکرار اور حدود کے حالات کی تصدیق کی جاتی ہے</li><li><strong>انجینئرنگ پروٹوٹائپ</strong>: قابل عمل انجینئرنگ پروٹوٹائپ مشین بنائی جاتی ہے، استحکام، توانائی کی کھپت اور حفاظت کا تجربہ کیا جاتا ہے</li><li><strong>معیاری بڑے پیمانے پر پیداوار</strong>: توانائی کے معیاری کاری اور پیمائش کے نظام کے ذریعے ٹیکنالوجی کے پیرامیٹرز کا تعین کیا جاتا ہے، بڑے پیمانے پر پیداوار کا عمل قائم کیا جاتا ہے</li><li><strong>کھلا اشتراک</strong>: ٹیکنالوجی کے کھلے اور اشتراک کے طریقہ کار کے مطابق، بالغ ٹیکنالوجیز کو پوری تہذیب کے لیے کھولا جاتا ہے</li></ol><p>اس عمل کی بنیادی خصوصیت &quot;کم آلودگی کی تصدیق&quot; ہے۔ نامعلوم قوانین سے متعلق تمام تجربات کو الگ تھلگ جگہ میں انجام دینا چاہیے، اور تجربے کے نتائج صرف علم کی شکل میں واپس کیے جاتے ہیں، اس بات کو یقینی بناتے ہوئے کہ مرکزی جہات پر غیر قابو پانے والی قانون کی آلودگی نہیں ہوگی۔</p><h2 id="_4-ٹیکنالوجی-سسٹم-اور-چار-مراحل-کے-جہت-بڑھاؤ-کے-راستے-کا-مطابقت" tabindex="-1">4. ٹیکنالوجی سسٹم اور چار مراحل کے جہت بڑھاؤ کے راستے کا مطابقت <a class="header-anchor" href="#_4-ٹیکنالوجی-سسٹم-اور-چار-مراحل-کے-جہت-بڑھاؤ-کے-راستے-کا-مطابقت" aria-label="Permalink to &quot;4. ٹیکنالوجی سسٹم اور چار مراحل کے جہت بڑھاؤ کے راستے کا مطابقت&quot;">​</a></h2><p>ٹیکنالوجی سسٹم کی ترقی چار مراحل کے جہت بڑھاؤ کے راستے سے سختی سے مطابقت رکھتی ہے:</p><ul><li><strong>حقیقی بنیاد کی تیاری کا مرحلہ</strong>: بنیادی طور پر حقیقی سائنس اور ٹیکنالوجی کی پرت پر توجہ مرکوز کرنا، توانائی، مواصلات، نقل و حمل جیسے بنیادی ڈھانچے کو بہتر بنانا، ٹیکنالوجی کے اجارہ داری اور ڈیجیٹل فرق کو ختم کرنا</li><li><strong>سائنس اور ٹیکنالوجی کی طاقت افزائی کا مرحلہ</strong>: قانون کی طاقت افزائی کی پرت مکمل طور پر پھیل جاتی ہے، ضرب پھل کا تخمینہ انجن جیسی ٹیکنالوجیز تحقیق کی کارکردگی میں نمایاں اضافہ کرتی ہیں، اور توانائی کے معیاری کاری کا نظام قائم ہوتا ہے</li><li><strong>شعور کے ارتقاء کا مرحلہ</strong>: قانون کی انجینئرنگ کی پرت بالغ ہو جاتی ہے، خلائی قوانین، کاپی آئینہ، الگ تھلگ جگہ جیسی ٹیکنالوجیز عام ہو جاتی ہیں، اور شعور کے ڈومین انٹرفیس ٹیکنالوجی میں کامیابی حاصل ہوتی ہے</li><li><strong>بین سیاروں کی سمبیوسس کا مرحلہ</strong>: اینکر بنیادی ڈھانچے کی پرت بین-جہات نیٹ ورک کو احاطہ کرتی ہے، اور بین سیاروں کی سطح کے توانائی کی شیڈولنگ اور مواصلاتی نظام قائم ہوتے ہیں</li></ul><p>فی الحال ہینگ یوآن ژو حقیقی بنیاد کی تیاری سے سائنس اور ٹیکنالوجی کی طاقت افزائی میں منتقلی کے اہم دور میں ہے، اور قانون کی طاقت افزائی کی پرت کی متعدد بنیادی ٹیکنالوجیز لیبارٹری سے بڑے پیمانے پر پیداوار کی طرف بڑھ رہی ہیں۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>ٹیکنالوجی سسٹم کا جامع جائزہ اینکر سمبیوٹک تہذیب کی مادی بنیاد کو سمجھنے کا دروازہ ہے۔ یہ نہ تو حقیقی سائنس اور ٹیکنالوجی کی سادہ تکرار ہے، اور نہ ہی خیالی قوانین کا من مانی جمع کرنا، بلکہ ایک مکمل ٹیکنالوجی نمونہ ہے جس کا اصول &quot;حقیقت پر مبنی، قوانین کی بہتری&quot; ہے، مرکز قانون کی انجینئرنگ ہے، اور راستہ چار مراحل کے جہت بڑھاؤ کا ہے۔ بعد کے دستاویزات مخصوص ٹیکنالوجی شعبوں کی تفصیل سے بیان کریں گے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>61-ضرب پھل کی انجینئرنگ ایپلی کیشن</li><li>62-خلائی قانون کی ٹیکنالوجی کا نفاذ</li><li>67-اینکر ہارڈویئر اور بنیادی ڈھانچہ</li></ul>',21)])])}const q=a(e,[["render",l]]);export{p as __pageData,q as default};
